<script lang="ts">let {title,items,t}:{title:string;items:{label:string;value:number;tone?:string}[];t:(s:string)=>string}=$props();let total=$derived(items.reduce((n,item)=>n+item.value,0));</script>
<section class="card"><h2>{title}</h2>{#if total}<div class="status-bar" aria-hidden="true">{#each items.filter(i=>i.value) as item}<span class={item.tone??'info'} style:flex={item.value}></span>{/each}</div><ul>{#each items as item}<li><span class={'pill '+(item.tone??'info')}>{t(item.label)}</span><strong>{item.value}</strong></li>{/each}</ul>{:else}<p class="empty-state">{t('uxEmptyHint')}</p>{/if}</section>
<style>.status-bar{display:flex;gap:4px;height:14px;border-radius:5px;overflow:hidden;margin:22px 0}.status-bar span{background:#779b89}.status-bar .good{background:#2d9367}.status-bar .warning{background:#bd841e}.status-bar .bad{background:#bf6363}.status-bar .info{background:#587ba3}ul{list-style:none;padding:0;margin:0;display:grid;gap:12px}li{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #eff3f0;padding-bottom:10px}li:last-child{border:0;padding-bottom:0}strong{font-size:18px;font-variant-numeric:tabular-nums}</style>
